<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
$user=loggedUser();
if(!$user){header('Location: login.php?redirect=profile.php');exit;}
$pdo=db();
$stmt=$pdo->prepare('SELECT id,name,phone,email,role,status,email_verified,avatar_url,created_at,updated_at FROM users WHERE id=? LIMIT 1');
$stmt->execute([(int)$user['id']]);
$profile=$stmt->fetch();
if(!$profile){session_destroy();header('Location: login.php');exit;}
$addr=$pdo->prepare('SELECT * FROM user_addresses WHERE user_id=? ORDER BY is_default DESC,id DESC');
$addr->execute([(int)$user['id']]);$addresses=$addr->fetchAll();
$orderCount=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE user_id=?');$orderCount->execute([(int)$user['id']]);$orders=(int)$orderCount->fetchColumn();
$wishlistCount=$pdo->prepare('SELECT COUNT(*) FROM wishlist_items WHERE user_id=?');$wishlistCount->execute([(int)$user['id']]);$wishlist=(int)$wishlistCount->fetchColumn();
$cartCount=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) FROM cart_items WHERE user_id=?');$cartCount->execute([(int)$user['id']]);$cart=(int)$cartCount->fetchColumn();
$csrf=csrfToken();
function pe($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function avatarSrc(?string $v):string{return $v ? pe($v) : '';}
$initial=strtoupper(mb_substr((string)$profile['name'],0,1));
?>
