letter-spacing:.06em}.field input,.field select{width:100%;padding:13px 14px;border:1px solid var(--line);border-radius:13px;background:#0b1018;color:var(--text);outline:none;transition:.2s}.field input:focus,.field select:focus{border-color:rgba(244,197,66,.5);box-shadow:0 0 0 4px rgba(244,197,66,.07)}.form-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:15px}.message{display:none;padding:12px 14px;border-radius:13px;margin-bottom:13px;font-size:13px}.message.show{display:block}.message.ok{background:rgba(81,227,154,.08);border:1px solid rgba(81,227,154,.18);color:#92f1bd}.message.err{background:rgba(255,101,120,.08);border:1px solid rgba(255,101,120,.18);color:#ff9ba8}.photo-row{display:flex;align-items:center;gap:17px}.mini-avatar{width:74px;height:74px;border-radius:20px;background:#111722;border:1px solid var(--line);display:grid;place-items:center;font-size:27px;font-weight:900;color:var(--gold);overflow:hidden}.mini-avatar img{width:100%;height:100%;object-fit:cover}.photo-actions{display:flex;gap:8px;flex-wrap:wrap}.upload-label{display:inline-flex;align-items:center;gap:8px;cursor:pointer}.upload-label input{display:none}.addresses{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.address{border:1px solid var(--line);background:rgba(255,255,255,.025);border-radius:18px;padding:16px;position:relative}.address.default{border-color:rgba(244,197,66,.35);box-shadow:0 10px 35px rgba(244,197,66,.05)}.address-top{display:flex;justify-content:space-between;gap:8px;align-items:center}.tag{font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.08em;color:var(--gold);padding:6px 8px;border-radius:999px;background:rgba(244,197,66,.08)}.default-tag{font-size:10px;color:var(--green);font-weight:850}.address p{color:#ccd4e0;font-size:13px;line-height:1.6;margin:12px 0}.address-actions{display:flex;gap:7px;flex-wrap:wrap}.tiny{font-size:11px;padding:8px 10px}.password-note{font-size:11px;color:var(--muted);margin-top:7px}.danger{color:#ff9ba8}.empty{padding:24px;text-align:center;border:1px dashed #2c3545;border-radius:17px;color:var(--muted)}.photo-note{color:var(--muted);font-size:11px}.modal{position:fixed;inset:0;background:rgba(0,0,0,.72);backdrop-filter:blur(10px);display:none;align-items:center;justify-content:center;padding:16px;z-index:100}.modal.open{display:flex}.modal-box{width:min(620px,100%);max-height:92vh;overflow:auto;background:#0e131c;border:1px solid var(--line);border-radius:24px;box-shadow:0 35px 110px rgba(0,0,0,.55);animation:pop .25s ease}.modal-head{display:flex;justify-content:space-between;align-items:center;padding:18px 20px;border-bottom:1px solid var(--line);position:sticky;top:0;background:#0e131c;z-index:2}.modal-head h2{margin:0}.close{width:37px;height:37px;border-radius:11px;border:1px solid var(--line);background:rgba(255,255,255,.05);color:var(--text);cursor:pointer}.modal-body{padding:20px}@keyframes pop{from{opacity:0;transform:translateY(10px) scale(.97)}to{opacity:1;transform:none}}@keyframes float{50%{transform:translateY(-4px)}}
