<script>const CSRF=<?=json_encode($csrf)?>;const API='profile-api.php';const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];function msg(el,text,ok=false){el.textContent=text;el.className='message show '+(ok?'ok':'err')}async function send(form,action){const fd=new FormData(form);fd.append('action',action);const r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-CSRF-Token':CSRF}});return await r.json()}
$('#profileForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;b.textContent='Saving…';try{const j=await send(e.target,'update-profile');if(!j.ok)throw new Error(j.message);$('#sideName').textContent=j.data.user.name;$('#sideEmail').textContent=j.data.user.email;msg($('#profileMsg'),j.message,true)}catch(x){msg($('#profileMsg'),x.message)}finally{b.disabled=false;b.textContent='Save Changes'}});
$('#passwordForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;b.textContent='Updating…';try{const j=await send(e.target,'change-password');if(!j.ok)throw new Error(j.message);e.target.reset();msg($('#passwordMsg'),j.message,true)}catch(x){msg($('#passwordMsg'),x.message)}finally{b.disabled=false;b.textContent='Change Password'}});
$('#avatarInput').addEventListener('change',async e=>{if(!e.target.files[0])return;const fd=new FormData();fd.append('action','upload-avatar');fd.append('avatar',e.target.files[0]);try{const r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-CSRF-Token':CSRF}}),j=await r.json();if(!j.ok)throw new Error(j.message);const src=j.data.avatar_url+'?v='+Date.now();$('#miniAvatar').innerHTML='<img src="'+src+'" alt="Profile photo">';$('#sideAvatar').innerHTML='<img src="'+src+'" alt="Profile photo">';msg($('#profileMsg'),j.message,true)}catch(x){msg($('#profileMsg'),x.message)}e.target.value=''});
$('#removeAvatar').onclick=async()=>{if(!confirm('Remove your profile photo?'))return;const fd=new FormData();fd.append('action','delete-avatar');try{const r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-CSRF-Token':CSRF}}),j=await r.json();if(!j.ok)throw new Error(j.message);const initial=<?=json_encode($initial)?>;$('#miniAvatar').textContent=initial;$('#sideAvatar').textContent=initial;msg($('#profileMsg'),j.message,true)}catch(x){msg($('#profileMsg'),x.message)}};
const modal=$('#addressModal');$('#addAddress').onclick=()=>modal.classList.add('open');$('#closeAddress').onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};$('#addressForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;b.textContent='Saving…';try{const j=await send(e.target,'add-address');if(!j.ok)throw new Error(j.message);location.reload()}catch(x){msg($('#addressMsg'),x.message)}finally{b.disabled=false;b.textContent='Save Address'}});
document.addEventListener('click',async e=>{const def=e.target.closest('[data-default]'),del=e.target.closest('[data-delete]');if(def){const fd=new FormData();fd.append('action','set-default-address');fd.append('address_id',def.dataset.default);const r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-CSRF-Token':CSRF}}),j=await r.json();if(!j.ok)return alert(j.message);location.reload()}if(del){if(!confirm('Delete this saved address?'))return;const fd=new FormData();fd.append('action','delete-address');fd.append('address_id',del.dataset.delete);const r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-CSRF-Token':CSRF}}),j=await r.json();if(!j.ok)return alert(j.message);location.reload()}});</script>
